frappe.ui.form.on('Operative', {
  open_opr_03: function(frm) {
    const modal = new frappe.ui.Dialog({
      title: 'Operative Record For Pterygium Surgery',
      size: 'large',
      fields: [{ fieldname: 'canvas_wrapper', fieldtype: 'HTML' }],
      primary_action_label: 'บันทึก',
      primary_action: async () => {
        const finalCanvas = document.createElement('canvas');
        finalCanvas.width = canvas.width;
        finalCanvas.height = canvas.height;
        const finalCtx = finalCanvas.getContext('2d');

        finalCtx.drawImage(document.getElementById('bg_img'), 0, 0);
        finalCtx.drawImage(canvas, 0, 0);

        const dataURL = finalCanvas.toDataURL('image/png');
        await frm.set_value('drawing_image', dataURL);
        await frm.save();
        await frm.reload_doc();

        const html = `<div style="text-align:center;">
          <p>🖼️ <b>ภาพที่บันทึก:</b></p>
          <img src="${frm.doc.drawing_image}" style="max-width:100%; border:1px solid #ccc; padding:5px;">
        </div>`;

        frappe.msgprint({
          title: __('✅ บันทึกภาพเรียบร้อยแล้ว'),
          indicator: 'green',
          message: html,
        });

        modal.hide();
      }
    });

    modal.show();
    const wrapper = modal.fields_dict.canvas_wrapper.$wrapper;

    wrapper.html(`
      <div style="position: relative; display: inline-block;">
        <img id="bg_img" src="/files/pic_opr_03.png" style="max-width:100%; display:block;">
        <canvas id="draw_canvas" style="position:absolute; top:0; left:0;"></canvas>
      </div>

      <div style="margin-top:20px;">🖊️ <b>ขนาดปากกา:</b><br>
        <input type="range" id="pencil_size" min="1" max="20" value="2">
      </div>

      <div style="margin-top:15px;">🎨 <b>สีของปากกา:</b><br>
        <input type="color" id="pencil_color" value="#000000">
      </div>

      <div style="margin-top:15px;">
        <label><input type="checkbox" id="eraser_toggle"> 🧽 <b>เปิดใช้ยางลบ</b></label><br>
        <label>ขนาดยางลบ:</label>
        <input type="range" id="eraser_size" min="5" max="50" value="10">
      </div>

      <div style="margin-top:20px;">
        <button id="undo_btn">↩️ Undo</button>
        <button id="redo_btn">↪️ Redo</button>
        <button id="save_btn">💾 ดาวน์โหลด</button>
      </div>
    `);

    const canvas = wrapper.find('#draw_canvas')[0];
    const ctx = canvas.getContext('2d');
    const pencilSize = wrapper.find('#pencil_size');
    const eraserSize = wrapper.find('#eraser_size');
    const pencilColor = wrapper.find('#pencil_color');
    const eraserToggle = wrapper.find('#eraser_toggle');
    const undoBtn = wrapper.find('#undo_btn');
    const redoBtn = wrapper.find('#redo_btn');
    const saveBtn = wrapper.find('#save_btn');

    let drawing = false, scale = 1, offsetX = 0, offsetY = 0;
    let isPanning = false, startPan = {};

    const undoStack = [];
    let cStep = -1;

    function saveState() {
      cStep++;
      if (cStep < undoStack.length) undoStack.length = cStep;
      undoStack.push(canvas.toDataURL());
    }

    const img = wrapper.find('#bg_img')[0];
    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      saveState();
    };

    // 📌 Mouse Events
    canvas.addEventListener('mousedown', e => {
      if (e.button === 1 || e.button === 2) {
        isPanning = true;
        startPan = { x: e.clientX, y: e.clientY };
        return;
      }
      drawing = true;
      ctx.beginPath();
      const { x, y } = getCoords(e);
      ctx.moveTo(x, y);
    });

    canvas.addEventListener('mouseup', () => {
      if (drawing) saveState();
      drawing = false;
      isPanning = false;
      ctx.beginPath();
    });

    canvas.addEventListener('mousemove', function(e) {
      if (isPanning) {
        offsetX += e.clientX - startPan.x;
        offsetY += e.clientY - startPan.y;
        startPan = { x: e.clientX, y: e.clientY };
        redrawAll();
        return;
      }
      if (!drawing) return;
      const { x, y } = getCoords(e);
      drawLine(x, y);
    });

    canvas.addEventListener('mouseleave', () => {
      drawing = false;
      ctx.beginPath();
    });

    // 📌 Touch Events
    canvas.addEventListener('touchstart', e => {
      e.preventDefault();
      drawing = true;
      ctx.beginPath();
      const touch = e.touches[0];
      const { x, y } = getCoords(touch);
      ctx.moveTo(x, y);
    }, { passive: false });

    canvas.addEventListener('touchmove', e => {
      e.preventDefault();
      if (!drawing) return;
      const touch = e.touches[0];
      const { x, y } = getCoords(touch);
      drawLine(x, y);
    }, { passive: false });

    canvas.addEventListener('touchend', e => {
      drawing = false;
      ctx.beginPath();
      saveState();
    });

    // 📌 Wheel Zoom
    canvas.addEventListener('wheel', e => {
      e.preventDefault();
      const zoom = e.deltaY < 0 ? 1.1 : 0.9;
      const mx = e.offsetX, my = e.offsetY;
      offsetX = mx - (mx - offsetX) * zoom;
      offsetY = my - (my - offsetY) * zoom;
      scale *= zoom;
      redrawAll();
    });

    undoBtn.on('click', () => {
      if (cStep > 0) {
        cStep--;
        restoreState(undoStack[cStep]);
      }
    });

    redoBtn.on('click', () => {
      if (cStep < undoStack.length - 1) {
        cStep++;
        restoreState(undoStack[cStep]);
      }
    });

    saveBtn.on('click', () => {
      const exportCanvas = document.createElement('canvas');
      exportCanvas.width = canvas.width;
      exportCanvas.height = canvas.height;
      const exportCtx = exportCanvas.getContext('2d');
      exportCtx.drawImage(document.getElementById('bg_img'), 0, 0);
      exportCtx.drawImage(canvas, 0, 0);
      const link = document.createElement('a');
      link.download = 'drawing.png';
      link.href = exportCanvas.toDataURL('image/png');
      link.click();
    });

    function restoreState(dataURL) {
      const img = new Image();
      img.src = dataURL;
      img.onload = () => {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
        redrawAll();
      };
    }

    function drawLine(x, y) {
      const isE = eraserToggle.prop('checked');
      const size = isE ? eraserSize.val() : pencilSize.val();
      ctx.lineCap = 'round';
      if (isE) {
        ctx.clearRect(x - size / 2, y - size / 2, size, size);
      } else {
        ctx.lineWidth = size;
        ctx.strokeStyle = pencilColor.val();
        ctx.lineTo(x, y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(x, y);
      }
    }

    function getCoords(e) {
      const rect = canvas.getBoundingClientRect();
      const clientX = e.clientX ?? e.pageX;
      const clientY = e.clientY ?? e.pageY;
      return {
        x: (clientX - rect.left - offsetX) / scale,
        y: (clientY - rect.top - offsetY) / scale
      };
    }

    function redrawAll() {
      const img = new Image();
      img.src = undoStack[cStep];
      img.onload = () => {
        ctx.setTransform(scale, 0, 0, scale, offsetX, offsetY);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
      };
    }
  }
});

