frappe.ui.form.on('Operative', {
    // ✅ start / end ยัง auto-save
    start: function(frm) { if (frm.doc.start && frm.doc.or_num) frm.save(); },
    end: function(frm) { if (frm.doc.end && frm.doc.or_num) frm.save(); },

    // ❌ post2, postplana, post, post3 ไม่ auto-save
    // (จะอัปเดต OR ก็ตอน user กด Save เอง)

    // ✅ หลังจาก save แล้ว ค่อยอัปเดต OR
    after_save: function(frm) {
        if (!frm.doc.or_num) return;

        let fields_to_update = {};

        // ⏱ Start
        if (frm.doc.start) {
            fields_to_update.start_operation_date = frappe.datetime.get_today();
            fields_to_update.start_operation_time = frm.doc.start;
            fields_to_update.wf_or_state = "กำลังผ่าตัด";
        }

        // ⏱ End
        if (frm.doc.end) {
            fields_to_update.end_operation_date = frappe.datetime.get_today();
            fields_to_update.end_operation_time = frm.doc.end;
            fields_to_update.wf_or_state = "สิ้นสุดการผ่าตัด";
        }

        // 📝 Diagnosis Post (รวมค่า post2, postplana, post, post3)
        let values = [
            frm.doc.post2,
            frm.doc.postplana,
            frm.doc.post,
            frm.doc.post3
        ].filter(Boolean);  // กรองค่าว่าง/null ออก

        if (values.length) {
            fields_to_update.diagnosis_post = values.join(", ");
            fields_to_update.wf_or_state = "สิ้นสุดการผ่าตัด";
        }

        // 🚀 Call อัปเดต OR
        if (Object.keys(fields_to_update).length) {
            frappe.call({
                method: "frappe.client.set_value",
                freeze: true,
                args: {
                    doctype: "OR",
                    name: frm.doc.or_num,
                    fieldname: fields_to_update
                },
                callback: function(res) {
                    if (!res.exc) {
                        frappe.show_alert({ message: __("✅ OR อัปเดตสำเร็จ"), indicator: "green" });
                    } else {
                        frappe.msgprint(__("❌ OR อัปเดตไม่สำเร็จ"));
                        console.error(res.exc);
                    }
                }
            });
        }
    }
});

