// ✅ ฟังก์ชันดึงชื่อและตำแหน่งจากผู้ใช้งานที่ login อยู่
function set_user_info_from_login(frm, recorded_by_field, position_field) {
  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: "User",
      name: frappe.session.user
    },
    callback: function(r) {
      if (r.message) {
        frm.set_value(recorded_by_field, r.message.full_name || r.message.first_name || frappe.session.user);
        if (r.message.position) {
          frm.set_value(position_field, r.message.position);
        } else {
          frm.set_value(position_field, '');
        }
      } else {
        frappe.msgprint("ไม่พบข้อมูลผู้ใช้งาน");
      }
    }
  });
}

