      if (cStep < undoStack.length) undoStack.length = cStep;
      undoStack.push(canvas.toDataURL());
    }

    const img = wrapper.find('#bg_img')[0];
img.onload = () => {
  const realW = img.naturalWidth;
  const realH = img.naturalHeight;

  canvas.width = realW;
  canvas.height = realH;

  saveState();
};



    // 🖱️ Mouse
    canvas.addEventListener('mousedown', e => {
      if (e.button === 1 || e.button === 2) {
        isPanning = true;
        startPan = { x: e.clientX, y: e.clientY };
        return;
      }
      drawing = true;
      ctx.beginPath();
      const { x, y } = getCoords(e);
      ctx.moveTo(x, y);
    });

    canvas.addEventListener('mouseup', () => {
      if (drawing) saveState();
      drawing = false;
      isPanning = false;
      ctx.beginPath();
    });

    canvas.addEventListener('mousemove', function(e) {
      if (isPanning) {
        offsetX += e.clientX - startPan.x;
        offsetY += e.clientY - startPan.y;
        startPan = { x: e.clientX, y: e.clientY };
        redrawAll();
        return;
      }
      if (!drawing) return;
      const { x, y } = getCoords(e);
      drawLine(x, y);
    });

    canvas.addEventListener('mouseleave', () => {
      drawing = false;
      ctx.beginPath();
    });

    // 🤳 Touch
    canvas.addEventListener('touchstart', e => {
      e.preventDefault();
      drawing = true;
      ctx.beginPath();
      const touch = e.touches[0];
      const { x, y } = getCoords(touch);
      ctx.moveTo(x, y);
    }, { passive: false });

    canvas.addEventListener('touchmove', e => {
      e.preventDefault();
      if (!drawing) return;
      const touch = e.touches[0];
      const { x, y } = getCoords(touch);
      drawLine(x, y);
    }, { passive: false });

    canvas.addEventListener('touchend', e => {
      drawing = false;
      ctx.beginPath();
      saveState();
    });

    // 🔍 Zoom
    canvas.addEventListener('wheel', e => {
      e.preventDefault();
      const zoom = e.deltaY < 0 ? 1.1 : 0.9;
      const mx = e.offsetX, my = e.offsetY;
      offsetX = mx - (mx - offsetX) * zoom;
      offsetY = my - (my - offsetY) * zoom;
      scale *= zoom;
      redrawAll();
    });

    undoBtn.on('click', () => {
      if (cStep > 0) {
        cStep--;
        restoreState(undoStack[cStep]);
      }
    });

    redoBtn.on('click', () => {
      if (cStep < undoStack.length - 1) {
        cStep++;
        restoreState(undoStack[cStep]);
      }
    });

    saveBtn.on('click', () => {
      const exportCanvas = document.createElement('canvas');
      exportCanvas.width = canvas.width;
      exportCanvas.height = canvas.height;
      const exportCtx = exportCanvas.getContext('2d');
      exportCtx.setTransform(scale, 0, 0, scale, offsetX, offsetY);
      exportCtx.drawImage(document.getElementById('bg_img'), 0, 0);
      exportCtx.drawImage(canvas, 0, 0);
      const link = document.createElement('a');
      link.download = 'drawing.png';
      link.href = exportCanvas.toDataURL('image/png');
      link.click();
    });

    function restoreState(dataURL) {
      const img = new Image();
      img.src = dataURL;
      img.onload = () => {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
        redrawAll();
      };
    }

    function drawLine(x, y) {
      const isE = eraserToggle.prop('checked');
      const size = isE ? eraserSize.val() : pencilSize.val();
      ctx.lineCap = 'round';
      if (isE) {
        ctx.clearRect(x - size / 2, y - size / 2, size, size);
      } else {
        ctx.lineWidth = size;
        ctx.strokeStyle = pencilColor.val();
        ctx.lineTo(x, y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(x, y);
      }
    }

    function getCoords(e) {
  const rect = canvas.getBoundingClientRect();
  const clientX = e.clientX ?? e.pageX;
  const clientY = e.clientY ?? e.pageY;

  // คำนวณอัตราส่วนระหว่าง "ขนาดแสดงผลบนจอ" และ "ขนาดจริงของ canvas"
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;

  return {
    x: (clientX - rect.left) * scaleX,
    y: (clientY - rect.top) * scaleY
  };
}


    function redrawAll() {
      const img = new Image();
      img.src = undoStack[cStep];
      img.onload = () => {
        ctx.setTransform(scale, 0, 0, scale, offsetX, offsetY);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
      };
    }
  }
});

